const WORDS = VSETS.flatMap(s=>s.words.map(w=>w.slice(0,4)));

const VUNITS = VSETS.map((set,k)=>{
  const all = VSETS.flatMap((s,j)=>s.words.map(w=>({w,j})));
  const near = w => new Set(NEAR.filter(g=>g.includes(w)).flat());
  const cloze = (w,i) => {
    const bad = near(w[0]);
    const pool = all.filter(x=>x.j!==k && x.w[1]===w[1] && !bad.has(x.w[0])).map(x=>x.w);
    const pick = []; let h = (k*31 + i*17 + w[0].length) % pool.length;
    while(pick.length<3){ const c = pool[h % pool.length]; if(!pick.includes(c)) pick.push(c); h += 1; }
    return { p:w[4], q:Q_WORD, c:[w[0], ...pick.map(x=>x[0])], word:w[0], d:set.d||2,
      e:`"${w[0]}" means ${w[2]}, which fits the clue in the sentence. ` + pick.map(x=>`"${x[0]}" means ${x[2]}.`).join(' ') };
  };
  const ws = set.words;
  const A = [{t:'m', d:1, pairs:ws.slice(0,4).map(w=>[w[0],w[2]])}, ...ws.slice(0,5).map(cloze)];
  const B = [{t:'m', d:1, pairs:ws.slice(5,9).map(w=>[w[0],w[2]])}, ...ws.slice(5,10).map((w,i)=>cloze(w,i+5))];
  const meaning = (w,i) => { const others=[1,2,3].map(s=>ws[(i+s*3)%10]); return { t:'mean', d:1, word:w[0], p:`<p class="vword"><b>${w[0]}</b> <span>${w[1]}</span></p><p>“${w[3]}”</p>`, q:'Which choice best gives the meaning of the word as it is used in the sentence?',
      c:[w[2], ...others.map(o=>o[2])], e:`"${w[0]}" means ${w[2]}.` + others.map(o=>` ${o[2].charAt(0).toUpperCase()+o[2].slice(1)} would be "${o[0]}".`).join('') }; };
  const spell = w => ({ t:'type', d:2, word:w[0], ans:w[0], p:w[4], q:`Type the missing word. It means “${w[2]}” and starts with “${w[0][0]}”.`, e:`The word is "${w[0]}": ${w[2]}. Example: ${w[3]}` });
  const C = [...[1,3,5,7,9].map(i=>meaning(ws[i],i)), ...[0,4,8].map(i=>spell(ws[i]))];
  return { id:'v'+(k+1), sec:4, vocab:true, title:set.title, setNo:k+1,
    tip:'Read the whole sentence before the choices. Find the clue (a colon, "but," "because," an example), predict your own word, then pick the closest match.',
    lessons:[A,B,C], meaning };
});
